WITH unpivoted AS (SELECT id, store_id, metric_name, reading FROM (SELECT id, store_id, discount, amount, shipping_fee FROM orders) src UNPIVOT (reading FOR metric_name IN (discount AS DISCOUNT_VAL, amount AS AMOUNT, shipping_fee AS SHIPPING_FEE))) SELECT CASE WHEN reading >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END AS reading_tier, store_id, COUNT(CASE WHEN metric_name = 'DISCOUNT_VAL' THEN 1 END) AS discount_val_count, APPROX_PERCENTILE(reading, ARRAY(0.25, 0.5, 0.75)) AS reading_quartiles, SUM(reading) FILTER (WHERE metric_name = 'SHIPPING_FEE') AS shipping_fee_total_reading FROM unpivoted GROUP BY CASE WHEN reading >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END, store_id ORDER BY shipping_fee_total_reading DESC NULLS LAST;
